CREATE TABLE campuses (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255), active BOOLEAN NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE categories (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(255), active BOOLEAN NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL);
CREATE TABLE campus_locations (id BIGINT AUTO_INCREMENT PRIMARY KEY, campus_id BIGINT NOT NULL, name VARCHAR(120) NOT NULL, active BOOLEAN NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(campus_id) REFERENCES campuses(id), UNIQUE(campus_id,name));
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, campus_id BIGINT NOT NULL, membership VARCHAR(20) NOT NULL, suspended BOOLEAN NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(campus_id) REFERENCES campuses(id));
CREATE TABLE item_reports (id BIGINT AUTO_INCREMENT PRIMARY KEY, owner_id BIGINT NOT NULL, type VARCHAR(10) NOT NULL, title VARCHAR(120) NOT NULL, category_id BIGINT NOT NULL, colour VARCHAR(50), description VARCHAR(2000) NOT NULL, location_id BIGINT NOT NULL, event_date DATE NOT NULL, status VARCHAR(20) NOT NULL, image_key VARCHAR(255), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(owner_id) REFERENCES users(id), FOREIGN KEY(category_id) REFERENCES categories(id), FOREIGN KEY(location_id) REFERENCES campus_locations(id), CHECK(type IN ('LOST','FOUND')), CHECK(status IN ('ACTIVE','CLAIMED','RETURNED','CLOSED','HIDDEN')));
CREATE INDEX idx_report_search ON item_reports(status,type,category_id,location_id,event_date);
CREATE INDEX idx_report_owner ON item_reports(owner_id,created_at);
CREATE TABLE matches (id BIGINT AUTO_INCREMENT PRIMARY KEY, lost_report_id BIGINT NOT NULL, found_report_id BIGINT NOT NULL, score INT NOT NULL, status VARCHAR(20) NOT NULL, explanation VARCHAR(255) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(lost_report_id) REFERENCES item_reports(id), FOREIGN KEY(found_report_id) REFERENCES item_reports(id), UNIQUE(lost_report_id,found_report_id), CHECK(score BETWEEN 0 AND 100), CHECK(lost_report_id<>found_report_id));
CREATE TABLE match_dismissals (id BIGINT AUTO_INCREMENT PRIMARY KEY, match_id BIGINT NOT NULL, user_id BIGINT NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(match_id) REFERENCES matches(id), FOREIGN KEY(user_id) REFERENCES users(id), UNIQUE(match_id,user_id));
CREATE TABLE claims (id BIGINT AUTO_INCREMENT PRIMARY KEY, report_id BIGINT NOT NULL, claimant_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, reviewer_id BIGINT, decided_at TIMESTAMP(6), handover_message VARCHAR(255), created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(report_id) REFERENCES item_reports(id), FOREIGN KEY(claimant_id) REFERENCES users(id), FOREIGN KEY(reviewer_id) REFERENCES users(id), UNIQUE(report_id,claimant_id), CHECK(status IN ('PENDING','APPROVED','REJECTED','WITHDRAWN')));
CREATE INDEX idx_claim_review ON claims(report_id,status);
CREATE TABLE claim_secrets (id BIGINT AUTO_INCREMENT PRIMARY KEY, claim_id BIGINT NOT NULL UNIQUE, verification VARCHAR(2000) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(claim_id) REFERENCES claims(id));
CREATE TABLE notifications (id BIGINT AUTO_INCREMENT PRIMARY KEY, recipient_id BIGINT NOT NULL, type VARCHAR(30) NOT NULL, message VARCHAR(255) NOT NULL, report_id BIGINT, is_read BOOLEAN NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(recipient_id) REFERENCES users(id));
CREATE INDEX idx_notification_recipient ON notifications(recipient_id,is_read,created_at);
CREATE TABLE moderation_actions (id BIGINT AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT NOT NULL, target_type VARCHAR(30) NOT NULL, target_id BIGINT NOT NULL, action VARCHAR(40) NOT NULL, reason VARCHAR(1000) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(actor_id) REFERENCES users(id));
CREATE TABLE report_flags (id BIGINT AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT NOT NULL, report_id BIGINT NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP(6) NOT NULL, updated_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(reporter_id) REFERENCES users(id), FOREIGN KEY(report_id) REFERENCES item_reports(id), UNIQUE(reporter_id,report_id));
